return ['domain'=>'zinn-order-updates','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-order-updates','pot-creation-date'=>'2026-11-11T11:19:43+00:00','po-revision-date'=>'2026-11-11T11:19:43+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Order Updates'=>'Zinn® Order Updates','https://zinndigital.com/wordpress-plugins/zinn-order-updates'=>'https://zinndigital.com/wordpress-plugins/zinn-order-updates','SMS and WhatsApp order updates for your store, sent through Zinn® Campaigns under your store\'s own name. Connect in one click; no keys to paste.'=>'Ažuriranja narudžbi putem SMS-a i WhatsAppa za vašu trgovinu, poslana putem usluge Zinn® Campaigns pod vlastitim nazivom vaše trgovine. Povežite se jednim klikom; nema ključeva za lijepljenje.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Read and send SMS and WhatsApp order updates for this store.'=>'Čitajte i šaljite ažuriranja narudžbi putem SMS-a i WhatsAppa za ovu trgovinu.','The WooCommerce order ID.'=>'ID narudžbe za WooCommerce.','Get order messages'=>'Dohvati poruke narudžbe','Lists every SMS or WhatsApp update for one order, newest first, with its outcome. The phone number is masked.'=>'Prikazuje svako ažuriranje putem SMS-a ili WhatsAppa za jednu narudžbu, najnovije prvo, zajedno s njegovim ishodom. Telefonski broj je maskiran.','Send an order update'=>'Pošaljite ažuriranje narudžbe','Sends one approved order update (never free text) to the shopper of the order, only if they agreed to receive it. Reusing a request_id never sends twice.'=>'Šalje jedno odobreno ažuriranje narudžbe (nikada slobodan tekst) kupcu narudžbe, samo ako je pristao primiti ga. Ponovna upotreba request_id nikada ne šalje dvaput.','Which approved update to send.'=>'Koje odobreno ažuriranje poslati.','A unique ID for this send (8 to 64 letters, digits, dots, dashes or underscores). Send the same ID again to retry safely.'=>'Jedinstveni ID za ovo slanje (8 do 64 slova, znamenki, točaka, crtica ili podvlaka). Ponovno pošaljite isti ID kako biste sigurno ponovili pokušaj.','Optional https tracking link for a shipped update.'=>'Neobavezna https poveznica za praćenje poslanog ažuriranja.','Get connection health'=>'Dohvati stanje veze','Shows whether this store is connected to Zinn® Campaigns and what Zinn® Campaigns sees for it.'=>'Prikazuje je li ova trgovina povezana sa Zinn® Campaigns i što Zinn® Campaigns vidi za nju.','Choose one of the approved order updates.'=>'Odaberite jedno od odobrenih ažuriranja narudžbe.','The request ID must be 8 to 64 letters, digits, dots, dashes or underscores.'=>'ID zahtjeva mora sadržavati od 8 do 64 slova, znamenke, točke, crtice ili podvlake.','Connect this store to Zinn® Campaigns first.'=>'Prvo povežite ovu trgovinu sa Zinn® Campaigns.','There is no order with that ID on this store.'=>'U ovoj trgovini nema narudžbe s tim ID-jem.','Zinn® Campaigns could not be reached. Try again in a minute.'=>'Nije moguće uspostaviti vezu sa Zinn® Campaigns. Pokušajte ponovno za minutu.','Zinn® Campaigns refused the request.'=>'Zinn® Campaigns je odbio zahtjev.','Order Updates'=>'Ažuriranja narudžbe','Your store is connected to Zinn® Campaigns.'=>'Vaša je trgovina povezana sa Zinn® Campaigns.','Your store is disconnected. No messages will be sent.'=>'Vaša trgovina je odspojena. Poruke se neće slati.','That connection took too long or was started in another browser. Press Connect again.'=>'To povezivanje trajalo je predugo ili je pokrenuto u drugom pregledniku. Pritisnite ponovno Poveži.','Zinn® did not accept the connection. Press Connect again; if it keeps failing, contact Zinn® support.'=>'Zinn® nije prihvatio povezivanje. Pritisnite ponovno „Poveži se”; ako se problem nastavi, obratite se podršci za Zinn®.','Your site could not reach Zinn®. Check that your host allows outgoing connections, then press Connect again.'=>'Vaše web-mjesto nije moglo doći do Zinn®. Provjerite dopušta li vaš poslužitelj odlazne veze, a zatim ponovno pritisnite „Poveži se”.','Help'=>'Pomoć','Send your customers SMS and WhatsApp updates about their orders, under your store\'s own name, paid from your Zinn® credit.'=>'Šaljite svojim kupcima ažuriranja o njihovim narudžbama putem SMS-a i WhatsApp-a, pod nazivom vlastite trgovine, plaćena iz vašeg Zinn® kredita.','Connect opens Zinn® in this window. Sign in or create an account, approve this store, and you come straight back here. You never paste a key.'=>'Poveži otvara Zinn® u ovom prozoru. Prijavite se ili stvorite račun, odobrite ovu trgovinu i vratit ćete se izravno ovamo. Nikada ne lijepite ključ.','Connect to Zinn® Campaigns'=>'Povežite se sa Zinn® Campaigns','Connected, but Zinn® could not be reached just now. We will try again shortly.'=>'Povezano, ali se s uslugom Zinn® trenutačno nije moglo stupiti u kontakt. Pokušat ćemo ponovno uskoro.','Store'=>'Trgovina','Connected'=>'Povezano','Zinn® Campaigns'=>'Zinn® Campaigns','Open for your account'=>'Otvoreno za vaš račun','Not open for your account yet. Zinn® will e-mail you when it is.'=>'Još nije otvoreno za Vaš račun. Zinn® će Vam poslati e-poštu kada bude dostupno.','Disconnect'=>'Prekini vezu','You are not allowed to connect this store.'=>'Nemate dopuštenje za povezivanje ove trgovine.','You are not allowed to disconnect this store.'=>'Nemate dopuštenje za prekidanje veze s ovom trgovinom.','Send me order updates by SMS to my phone number. Message and data rates may apply. Reply STOP to stop.'=>'Šaljite mi ažuriranja narudžbe putem SMS-a na moj telefonski broj. Mogu se primijeniti naknade za poruke i podatke. Odgovorite sa STOP za prekid.','Connection'=>'Veza','You are not allowed to do that.'=>'Nemate dopuštenje za to.','Thank you. You can now ask for help and send reports to Zinn® support.'=>'Hvala Vam. Sada možete zatražiti pomoć i slati izvješća Zinn® podršci.','Consent withdrawn. Nothing is sent to Zinn® support until you agree again.'=>'Privola je povučena. Ništa se ne šalje podršci za Zinn® dok ponovno ne pristanete.','The Zinn® AI could not answer just now. Send your question to the team below; a person will reply.'=>'Zinn® AI trenutačno nije mogao odgovoriti. Pošaljite svoje pitanje timu u nastavku; odgovorit će vam osoba.','Glad that solved it.'=>'Drago nam je da je to riješilo problem.','Sent. Your ticket is %s; the team replies here and by e-mail.'=>'Poslano. Vaš tiket je %s; tim odgovara ovdje i putem e-pošte.','Fill in the subject, the message and, while your store is not connected, your e-mail address.'=>'Unesite predmet, poruku i, dok vaša trgovina nije povezana, svoju adresu e-pošte.','Zinn® did not accept the ticket. Check the fields and try again; if it keeps failing, e-mail support@zinndigital.com.'=>'Zinn® nije prihvatio prijavu. Provjerite polja i pokušajte ponovno; ako problem potraje, pošaljite e-poštu na support@zinndigital.com.','Too many requests in a short time. Wait a few minutes and try again.'=>'Previše zahtjeva u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno.','Reply sent.'=>'Odgovor je poslan.','That ticket is closed. Send a new ticket instead.'=>'Ta je prijava zatvorena. Umjesto toga pošaljite novu prijavu.','Your reply could not be sent. Try again in a moment.'=>'Vaš odgovor nije bilo moguće poslati. Pokušajte ponovo za nekoliko trenutaka.','Waiting on Zinn® support'=>'Čeka se podrška za Zinn®','Waiting on you'=>'Čeka se na vas','Answered'=>'Odgovoreno','Closed'=>'Zatvoreno','Report a bug'=>'Prijavite grešku','Send feedback'=>'Pošaljite povratne informacije','Request a feature'=>'Zatražite značajku','Ask for help'=>'Zatražite pomoć','Versions: WordPress, PHP, this plugin, WooCommerce (and whether it uses HPOS) and the supported plugins we detected'=>'Verzije: WordPress, PHP, ovaj priključak, WooCommerce (i koristi li HPOS) te podržani priključci koje smo otkrili','Your active theme and its version'=>'Vaša aktivna tema i njezina inačica','The list of installed plugins, their versions and whether each is active'=>'Popis instaliranih priključaka, njihove inačice i je li svaki od njih aktivan','Connection: your store address, whether it is connected, this install\'s id and whether Zinn® answered its last check (never the store\'s token)'=>'Povezivanje: adresa vaše trgovine, je li povezana, ID ove instalacije i je li Zinn® odgovorio na svoju posljednju provjeru (nikada token trgovine)','Zinn® Order Updates: Help'=>'Ažuriranja narudžbi za Zinn®: Pomoć','Withdraw my consent to send help requests'=>'Povuci moju privolu za slanje zahtjeva za pomoć','Help here is answered by Zinn Digital® Ltd. Before anything leaves your site, this is exactly what is sent, and where:'=>'Pomoć ovdje pruža Zinn Digital® Ltd. Prije nego što bilo što napusti Vašu web-stranicu, ovo je točno ono što se šalje i kamo:','A question you type: sent to the Zinn® AI at api.zinndigital.com, which answers from the Zinn® help articles.'=>'Pitanje koje upišete: šalje se u Zinn® AI na api.zinndigital.com, koji odgovara iz članaka pomoći za Zinn®.','A ticket you send: its subject, your message, your admin language and a reply e-mail address, sent to Zinn® support.'=>'Tiket koji šaljete: njegov predmet, vaša poruka, vaš administratorski jezik i adresa e-pošte za odgovor, poslani podršci za Zinn®.','Diagnostics: only the blocks you tick, each shown in full before you send. Never the store\'s token, passwords or your customers\' details.'=>'Dijagnostika: samo blokovi koje označite, a svaki se u cijelosti prikazuje prije slanja. Nikada token trgovine, lozinke ili podaci Vaših kupaca.','Your tickets: while your store is connected, this screen reads your tickets and the team\'s replies from Zinn®.'=>'Vaši tiketi: dok je vaša trgovina povezana, ovaj zaslon čita vaše tikete i odgovore tima iz Zinn®.','We record who agreed and when. You can withdraw at any time on this screen.'=>'Bilježimo tko je i kada pristao. Možete povući privolu u bilo kojem trenutku na ovom zaslonu.','Agree and continue'=>'Prihvati i nastavi','Ask the Zinn® AI'=>'Pitajte Zinn® AI','What do you need help with?'=>'S čime trebate pomoć?','Ask'=>'Pitajte','Help articles'=>'Članci pomoći','That solved it'=>'To je riješilo problem','Still need help? Send it to the team below.'=>'Još uvijek trebate pomoć? Pošaljite ga timu u nastavku.','Send it to the Zinn® team'=>'Pošaljite ga timu Zinn®','What is it?'=>'Što je to?','Subject'=>'Predmet','What happened? For a bug, the steps that show it.'=>'Što se dogodilo? Za programsku pogrešku, koraci koji je prikazuju.','Reply e-mail'=>'E-pošta za odgovor','Leave empty to use the e-mail of the Zinn® member who connected this store.'=>'Ostavite prazno kako biste upotrijebili e-poštu člana Zinn® koji je povezao ovu trgovinu.','Your store is not connected, so the team replies by e-mail.'=>'Vaša trgovina nije povezana, stoga tim odgovara e-poštom.','Diagnostics (optional). Tick a block to attach it; this is exactly what is sent.'=>'Dijagnostika (neobavezno). Označite blok kako biste ga priložili; točno to se šalje.','Send to Zinn® support'=>'Pošaljite podršci za Zinn®','My tickets'=>'Moji tiketi','Connect your store to follow your tickets here. Until then the team replies by e-mail.'=>'Povežite svoju trgovinu kako biste ovdje pratili svoje zahtjeve. Do tada tim odgovara e-poštom.','Your tickets could not be loaded just now. Try again in a moment.'=>'Vaši se tiketi trenutačno ne mogu učitati. Pokušajte ponovno za trenutak.','No tickets yet.'=>'Još nema prijava.','Zinn® support replied on %s:'=>'Podrška za Zinn® odgovorila je %s:','Your reply'=>'Vaš odgovor','Send reply'=>'Pošaljite odgovor','Zinn Digital®'=>'Zinn Digital®','Zinn® SMS and WhatsApp sign-up'=>'Prijava putem SMS-a i WhatsAppa za Zinn®','Lets visitors sign up for offers and news by SMS or WhatsApp. Unticked by default; marketing only.'=>'Omogućuje posjetiteljima prijavu za ponude i vijesti putem SMS-a ili WhatsAppa. Zadano nije označeno; samo u marketinške svrhe.','Sign-up settings'=>'Postavke registracije','Channel'=>'Kanal','SMS'=>'SMS','WhatsApp'=>'WhatsApp','Visitor chooses SMS or WhatsApp'=>'Posjetitelj odabire SMS ili WhatsApp','Zinn® SMS offers consent'=>'Pristanak za Zinn® SMS ponude','Zinn® WhatsApp offers consent'=>'Pristanak na ponude za Zinn® putem WhatsAppa','Records a marketing opt-in in Zinn® Campaigns for the phone number in this form.'=>'Bilježi marketinški pristanak u Zinn® Campaigns za telefonski broj u ovom obrascu.','Send me offers and news on WhatsApp to this number. Optional; unsubscribe any time.'=>'Šaljite mi ponude i novosti na WhatsApp na ovaj broj. Neobavezno; odjavite se u bilo kojem trenutku.','Send me offers and news by SMS to this number. Optional; unsubscribe any time by replying STOP. Message and data rates may apply.'=>'Šaljite mi ponude i novosti putem SMS-a na ovaj broj. Nije obavezno; pretplatu možete otkazati u bilo kojem trenutku slanjem odgovora STOP. Mogu se primijeniti tarife za poruke i prijenos podataka.','Connect this store to Zinn® Campaigns to show this sign-up form.'=>'Povežite ovu trgovinu sa Zinn® Campaigns kako biste prikazali ovaj obrazac za prijavu.','Mobile number'=>'Broj mobilnog telefona','How should we send them?'=>'Kako bismo ih trebali poslati?','Send me offers and news by the channel I chose above. Optional; unsubscribe any time.'=>'Šaljite mi ponude i novosti putem kanala koji sam odabrao/la iznad. Neobavezno; možete se odjaviti u bilo kojem trenutku.','Leave this empty'=>'Ostavite ovo prazno','Sign up'=>'Registrirajte se','Thank you, you are signed up. You can unsubscribe any time.'=>'Hvala vam, prijavljeni ste. Možete se odjaviti u bilo kojem trenutku.','Please enter your mobile number with its country code, for example +44 7700 900123.'=>'Unesite svoj broj mobilnog telefona s pozivnim brojem zemlje, na primjer +44 7700 900123.','Please tick the box to agree.'=>'Označite okvir za prihvaćanje.','This form was open for a long time. Please reload the page and send it again.'=>'Ovaj je obrazac bio dugo otvoren. Molimo ponovno učitajte stranicu i pošaljite ga ponovno.','Too many sign-ups from here. Please wait a few minutes and try again.'=>'Previše registracija odavde. Pričekajte nekoliko minuta i pokušajte ponovno.','We could not save your sign-up. Please check your number and try again.'=>'Nismo mogli spremiti vašu prijavu. Provjerite svoj broj i pokušajte ponovno.','my account endpoint slugmessages'=>'Poruke','Messages'=>'Poruke','Text me updates about my orders'=>'Šaljite mi novosti o mojim narudžbama putem SMS-a','Text me offers and news from this store'=>'Šaljite mi ponude i novosti iz ove trgovine putem SMS-a','Send me offers and news from this store on WhatsApp'=>'Šaljite mi ponude i novosti iz ove trgovine na WhatsApp','Order received'=>'Narudžba zaprimljena','Payment received'=>'Uplata primljena','Order on hold'=>'Narudžba na čekanju','Order shipped'=>'Narudžba poslana','Order completed'=>'Narudžba dovršena','Ready for pickup'=>'Spremno za preuzimanje','Payment failed'=>'Plaćanje nije uspjelo','Order cancelled'=>'Narudžba je otkazana','Order refunded'=>'Narudžba refundirana','Order update'=>'Ažuriranje narudžbe','Your message settings cover the mobile number on your orders with this store. Use the number from one of your orders.'=>'Vaše postavke poruka obuhvaćaju mobilni broj na Vašim narudžbama u ovoj trgovini. Upotrijebite broj iz jedne od svojih narudžbi.','Your message settings are saved.'=>'Vaše postavke poruka su spremljene.','Done. This store will not send you any more messages.'=>'Gotovo. Ova vam trgovina više neće slati poruke.','Please enter a mobile number with its country code, for example +44 7700 900123.'=>'Unesite broj mobilnog telefona s pozivnim brojem zemlje, na primjer +44 7700 900123.','We could not save your settings just now. Please try again in a minute.'=>'Trenutačno nismo mogli spremiti vaše postavke. Molimo pokušajte ponovno za minutu.','Your message settings cannot be shown just now. Please try again in a minute.'=>'Vaše postavke poruka trenutačno se ne mogu prikazati. Pokušajte ponovno za minutu.','Messages from this store'=>'Poruke iz ove trgovine','Save'=>'Spremi','Stop all messages'=>'Zaustavite sve poruke','Recent messages'=>'Nedavne poruke','This store has not sent you any messages yet.'=>'Ova vam trgovina još nije poslala nijednu poruku.','%1$s, order %2$s, %3$s'=>'%1$s, narudžba %2$s, %3$s','Sign in to manage the messages this store sends you.'=>'Prijavite se kako biste upravljali porukama koje vam ova trgovina šalje.','Zinn® message settings'=>'Postavke Zinn® poruka','Lets a signed-in shopper change the text messages your store sends them, stop them all, and see the last 20.'=>'Omogućuje prijavljenom kupcu promjenu tekstualnih poruka koje mu vaša trgovina šalje, potpuno zaustavljanje primanja i pregled zadnjih 20.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® Pro Membership: every Pro plugin, one licence'=>'Zinn® Pro članstvo: svaki Pro priključak, jedna licenca','The Pro versions of Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache and Zinn® Backups, and every Pro plugin we release next, from %s a year. A second membership adds Zinn® Chat Pro.'=>'Pro verzije dodataka Page Builder Sandwich, Tranzly, Zinn® SEO, Zinn® Cache i Zinn® Backups, te svaki sljedeći Pro dodatak koji objavimo, već od %s godišnje. Drugo članstvo dodaje Zinn® Chat Pro.','Zinn® hosting for WordPress'=>'Zinn® smještaj za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za osobe koje vode više od jednog web-mjesta.','The Zinn® marketplace'=>'Tržište Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web-stranice, domene i plasmane poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — angažirajte ljude koji se time profesionalno bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih profesionalaca: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im davanje ponuda.','See the Zinn Digital® release notes.'=>'Pogledajte napomene o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja za Zinn® nije izdala poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ovo web-mjesto pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja Zinn® (%s). Pokušajte ponovno za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','Order updates'=>'Ažuriranja narudžbe','Opted in (yes or no)'=>'Prijavljeno (da ili ne)','Channel (SMS or WhatsApp)'=>'Kanal (SMS ili WhatsApp)','WhatsApp link'=>'Poveznica na WhatsApp','Message us on WhatsApp'=>'Pošaljite nam poruku na WhatsAppu','Zinn® WhatsApp button'=>'Zinn® WhatsApp gumb','A button that opens a WhatsApp chat with your store. It shows only once your WhatsApp number is connected in Zinn® Campaigns.'=>'Gumb koji otvara WhatsApp razgovor s Vašom trgovinom. Prikazuje se tek nakon što povežete svoj WhatsApp broj u Zinn® Campaigns.','Button settings'=>'Postavke gumba','Button text'=>'Tekst gumba','Show to'=>'Prikaži za','Everyone'=>'Svi','Shoppers not yet getting order updates'=>'Kupci još ne primaju ažuriranja narudžbi','Connect your WhatsApp number in Zinn® Campaigns to show this button. Until then it shows nothing on your site.'=>'Povežite svoj WhatsApp broj u Zinn® Campaigns kako biste prikazali ovaj gumb. Do tada neće prikazivati ništa na vašoj web-stranici.']];